package warungaju;
import java.awt.*; import javax.swing.*;
public class LaporanPanel extends JPanel {
    public LaporanPanel(MainFrame f){setLayout(new BorderLayout(15,15));setBackground(MainFrame.LIGHT);setBorder(BorderFactory.createEmptyBorder(25,30,30,30));add(new JLabel("<html><h1>Laporan Keuangan</h1><font color='#60736b'>Ringkasan laba rugi dan posisi keuangan usaha</font></html>"),BorderLayout.NORTH);double in=f.laporan.pemasukan(f.transaksi),out=f.laporan.pengeluaran(f.transaksi);JTabbedPane tabs=new JTabbedPane();JPanel laba=new JPanel(new GridLayout(5,2,10,10));laba.setBackground(Color.WHITE);laba.setBorder(BorderFactory.createEmptyBorder(25,25,25,25));laba.add(new JLabel("Total pendapatan"));laba.add(new JLabel(UI.money(in)));laba.add(new JLabel("Harga pokok penjualan"));laba.add(new JLabel(UI.money(in*.45)));laba.add(new JLabel("Laba kotor"));laba.add(new JLabel(UI.money(in*.55)));laba.add(new JLabel("Biaya operasional"));laba.add(new JLabel(UI.money(out)));laba.add(new JLabel("Laba bersih"));laba.add(new JLabel(UI.money(in*.55-out)));tabs.addTab("Laporan Laba Rugi",laba);JPanel neraca=new JPanel(new GridLayout(3,2,10,10));neraca.setBackground(Color.WHITE);neraca.setBorder(BorderFactory.createEmptyBorder(25,25,25,25));neraca.add(new JLabel("Aset"));neraca.add(new JLabel(UI.money(in-out+3500000)));neraca.add(new JLabel("Liabilitas"));neraca.add(new JLabel(UI.money(0)));neraca.add(new JLabel("Ekuitas"));neraca.add(new JLabel(UI.money(in-out+3500000)));tabs.addTab("Neraca Sederhana",neraca);add(tabs,BorderLayout.CENTER);JPanel actions=new JPanel();actions.setOpaque(false);actions.add(UI.secondaryButton("Ekspor PDF (segera hadir)"));actions.add(UI.secondaryButton("Ekspor Excel (segera hadir)"));add(actions,BorderLayout.SOUTH);}
}
